entries[10601] = { ["name"] = "Schematic: Bright-Eye Goggles", ["text"] = "Use: Teaches you how to make Bright-Eye Goggles.\nRequires Classic Engineering (175)\nSell Price:\nBright-Eye Goggles\nBinds when equipped\nHead Cloth\n2 Armor\n+4 Stamina\n+ 5 Versatility\nDurability 70 / 70\nRequires Classic Engineering (1)\nSell Price:\nRequires Heavy Leather (6), Citrine (2)\nOptional Reagents: Optional Reagent Slot (#31)" }
entries[10602] = { ["name"] = "Schematic: Deadly Scope", ["text"] = "Use: Teaches you how to make a Deadly Scope.\nRequires Classic Engineering (210)\nSell Price:\nDeadly Scope\nUse: Attaches a permanent scope to a bow or gun that increases its damage by 2.\n\nAttaching this scope to a ranged weapon causes it to become soulbound. Cannot be applied to items higher than level 320.\nSell Price:\nRequires Mithril Tube , Aquamarine (2), Thick Leather (2)" }
entries[10603] = { ["name"] = "Schematic: Catseye Ultra Goggles", ["text"] = "Use: Teaches you how to make Catseye Ultra Goggles.\nRequires Classic Engineering (220)\nSell Price:\nCatseye Ultra Goggles\nBinds when equipped\nHead Cloth\n3 Armor\nDurability 70 / 70\nEquip: Moderately increases your stealth detection.\nRequires Classic Engineering (1)\nSell Price:\nRequires Thick Leather (4), Aquamarine (2), Catseye Elixir\nOptional Reagents: Optional Reagent Slot (#31)" }
entries[10604] = { ["name"] = "Schematic: Mithril Heavy-Bore Rifle", ["text"] = "Use: Teaches you how to make a Mithril Heavy-Bore Rifle.\nRequires Classic Engineering (220)\nSell Price:\nMithril Heavy-Bore Rifle\nBinds when equipped\nRanged Gun\n4 - 9 Damage Speed 3.00\n(2.2 damage per second)\n+3 Agility\n+5 Stamina\nDurability 75 / 75\nSell Price:\nRequires Mithril Tube (2), Unstable Trigger , Heavy Stock , Mithril Bar (6), Citrine (2)\nOptional Reagents: Optional Reagent Slot (#49)" }
entries[10605] = { ["name"] = "Schematic: Spellpower Goggles Xtreme", ["text"] = "Use: Teaches you how to make Spellpower Goggles Xtreme.\nRequires Classic Engineering (225)\nSell Price:\nSpellpower Goggles Xtreme\nBinds when equipped\nHead Cloth\n3 Armor\n+6 Intellect\nDurability 70 / 70\nRequires Classic Engineering (1)\nSell Price:\nRequires Thick Leather (4), Star Ruby (2)\nOptional Reagents: Optional Reagent Slot (#31)" }
entries[10606] = { ["name"] = "Schematic: Parachute Cloak", ["text"] = "Use: Teaches you how to make a Parachute Cloak.\nRequires Classic Engineering (225)\nSell Price:\nParachute Cloak\nBinds when equipped\nBack\n2 Armor\n+3 Agility\nUse: Reduces your fall speed for 10 sec. (30 Sec Cooldown)\nRequires Classic Engineering (1)\nSell Price:\nRequires Bolt of Mageweave (4), Shadow Silk (2), Unstable Trigger , Solid Blasting Powder (4)\nOptional Reagents: Optional Reagent Slot (#31)" }
entries[10607] = { ["name"] = "Schematic: Deepdive Helmet", ["text"] = "Use: Teaches you how to make a Deepdive Helmet.\nRequires Classic Engineering (230)\nSell Price:\nDeepdive Helmet\nCosmetic\nBinds when equipped\nHead Cosmetic\nDurability 70 / 70\nEquip: Allows underwater breathing.\nRequires Classic Engineering (1)\nUse: Add this appearance to your Warband collection.\nSell Price:\nRequires Mithril Bar (8), Mithril Casing , Truesilver Bar , Tigerseye (4), Malachite (4)" }
